// precision et recall (en % entiers) depuis une matrice de confusion.
// TODO : renvoyer l'accuracy pour les deux champs est faux — precision et
//        recall ont chacune leur formule et répondent à deux questions.
export function metrics(cm) {
  const acc = Math.round((cm.tp + cm.tn) / (cm.tp + cm.fp + cm.fn + cm.tn) * 100);
  return { precision: acc, recall: acc };
}

